// Normalize input so downstream nodes can reliably read `action` at the root.
// n8n may put the request JSON under `$json.body` depending on version/settings.
const body = ($json && typeof $json === 'object' && $json.body && typeof $json.body === 'object') ? $json.body : $json;
const action = String(body.action || '').trim();

// Preserve headers/query too (useful for auth/diagnostics).
const headers = ($json && $json.headers && typeof $json.headers === 'object') ? $json.headers : {};
const query = ($json && $json.query && typeof $json.query === 'object') ? $json.query : {};

return [{ json: { ...body, action, headers, query } }];

// Webhook payload shape differs by n8n version/settings.
// Prefer `body` when present, otherwise use the root json.
const b = ($json && typeof $json === 'object' && $json.body && typeof $json.body === 'object') ? $json.body : $json;

// Optional shared-secret auth (matches KUBE_OPS_COPILOT_N8N_BEARER_TOKEN)
const expected = ($env.KOC_N8N_BEARER_TOKEN || '').trim();
if (expected) {
  const h = ($json && $json.headers && typeof $json.headers === 'object') ? $json.headers : {};
  const auth = String((h.authorization || $headers.authorization || '')).trim();
  if (auth !== `Bearer ${expected}`) {
    throw new Error('unauthorized');
  }
}

const approvalId = String(b.approvalId || '').trim();
if (!approvalId) throw new Error('approvalId is required');

// Keep the message short & actionable
const summary = String(b.summary || '').trim();
const operation = String(b.operation || '').trim();
const target = String(b.target || '').trim();
const planPath = String(b.planPath || '').trim();

let details = String(b.details || '').trim();
if (details.length > 500) details = details.slice(0, 500) + '…';

// Persist in workflow static data (stored in n8n DB)
const store = getWorkflowStaticData('global');
store[approvalId] = {
  approvalId,
  decision: 'pending',
  approver: '',
  reason: 'awaiting decision',
  createdAt: new Date().toISOString(),
  summary,
  operation,
  target,
  planPath,
  details
};

// Build decision URLs for approve/deny buttons
const publicBase = ($env.KOC_PUBLIC_BASE_URL || '').replace(//+$/, '');
if (!publicBase) throw new Error('KOC_PUBLIC_BASE_URL is required (public URL to your n8n)');

const decisionSecret = ($env.KOC_DECISION_SECRET || '').trim();
if (!decisionSecret) throw new Error('KOC_DECISION_SECRET is required');

const approveUrl = `${publicBase}/webhook/koc-approval-decision?approvalId=${encodeURIComponent(approvalId)}&decision=approved&token=${encodeURIComponent(decisionSecret)}`;
const denyUrl = `${publicBase}/webhook/koc-approval-decision?approvalId=${encodeURIComponent(approvalId)}&decision=denied&token=${encodeURIComponent(decisionSecret)}`;

return [{ json: { approvalId, summary, operation, target, details, planPath, approveUrl, denyUrl } }];

const b = ($json && typeof $json === 'object' && $json.body && typeof $json.body === 'object') ? $json.body : $json;
const expected = ($env.KOC_N8N_BEARER_TOKEN || '').trim();
if (expected) {
  const h = ($json && $json.headers && typeof $json.headers === 'object') ? $json.headers : {};
  const auth = String((h.authorization || $headers.authorization || '')).trim();
  if (auth !== `Bearer ${expected}`) {
    throw new Error('unauthorized');
  }
}

const approvalId = String(b.approvalId || '').trim();
if (!approvalId) throw new Error('approvalId is required');

const store = getWorkflowStaticData('global');
const rec = store[approvalId];
if (!rec) {
  return [{ json: { approvalId, decision: 'pending', approver: '', reason: 'unknown approval id', raw: {} } }];
}
return [{ json: { approvalId, decision: rec.decision || 'pending', approver: rec.approver || '', reason: rec.reason || '', raw: rec } }];

const b = ($json && typeof $json === 'object' && $json.body && typeof $json.body === 'object') ? $json.body : $json;
const expected = ($env.KOC_N8N_BEARER_TOKEN || '').trim();
if (expected) {
  const h = ($json && $json.headers && typeof $json.headers === 'object') ? $json.headers : {};
  const auth = String((h.authorization || $headers.authorization || '')).trim();
  if (auth !== `Bearer ${expected}`) {
    throw new Error('unauthorized');
  }
}

const title = String(b.title || 'K8S AI Agent').trim();
let body = String(b.body || '').trim();
if (body.length > 800) body = body.slice(0, 800) + '…';

return [{ json: { title, body } }];

// Query params can appear under `$json.query` depending on n8n version.
const q = ($json && typeof $json === 'object' && $json.query && typeof $json.query === 'object') ? $json.query : $json;

const approvalId = String(q.approvalId || '').trim();
const decision = String(q.decision || '').trim().toLowerCase();
const token = String(q.token || '').trim();

const expected = ($env.KOC_DECISION_SECRET || '').trim();
if (!expected || token !== expected) {
  return [{ json: { ok: false, message: 'unauthorized' } }];
}
if (!approvalId) return [{ json: { ok: false, message: 'missing approvalId' } }];
if (!['approved','denied'].includes(decision)) return [{ json: { ok: false, message: 'invalid decision' } }];

const store = getWorkflowStaticData('global');
const rec = store[approvalId] || { approvalId };
rec.decision = decision;
rec.approver = 'n8n-link';
rec.reason = `clicked ${decision}`;
rec.decidedAt = new Date().toISOString();
store[approvalId] = rec;

return [{ json: { ok: true, approvalId, decision } }];
